import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CmvPqeTF.js";const h=JSON.parse('{"title":"更新记录","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1791540270000}'),s={name:"changelog.md"};function l(n,t,i,g,c,d){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="更新记录" tabindex="-1">更新记录 <a class="header-anchor" href="#更新记录" aria-label="Permalink to &quot;更新记录&quot;">​</a></h1><p>vShell 的版本更新记录，新版本在顶部追加。版本号与应用仓库的 git 标签一致。</p><p><strong>下载</strong>：<a href="https://github.com/crazy-airhead/vshell/releases/latest" target="_blank" rel="noreferrer">GitHub Releases 最新版</a> —— macOS（通用二进制 · Apple Silicon / Intel）、Windows（安装包 / 便携版）、Linux（deb · rpm · 便携版）。</p><blockquote><p>macOS 包未做公证：首次打开若被拦截，右键 App →「打开」，或执行 <code>xattr -d com.apple.quarantine /Applications/vshell.app</code> 后再打开。</p></blockquote><h2 id="v0-2-1-·-2026-10-09" tabindex="-1">v0.2.1 · 2026-10-09 <a class="header-anchor" href="#v0-2-1-·-2026-10-09" aria-label="Permalink to &quot;v0.2.1 · 2026-10-09&quot;">​</a></h2><ul><li><strong>修复</strong>：macOS 红绿灯与工具栏标题文本垂直居中对齐（改用 <code>MacTitleBarHiddenInset</code>，系统在工具栏条内自动居中灯位；此前灯位固定在 28pt 标题栏中线，高出工具栏中线约 12px）。</li><li><strong>修复</strong>：终端最后一行不再被编辑区底缘裁切（行数计算未扣除终端容器 6px 内边距，多算的行在部分窗口高度下溢出底缘被裁；现按真实可视区域适配行数，高度不足一行时底部留白）。</li><li><strong>修复</strong>：更改终端字号 / 字体、或在 Retina 与外接屏间移动窗口后，自动按新行高重新适配行数。</li></ul><h2 id="v0-2-0-·-2026-10-07" tabindex="-1">v0.2.0 · 2026-10-07 <a class="header-anchor" href="#v0-2-0-·-2026-10-07" aria-label="Permalink to &quot;v0.2.0 · 2026-10-07&quot;">​</a></h2><ul><li><strong>布局</strong>：整体界面重构为岛屿（Islands）设计语言 —— 画布 + 浮动圆角岛，统一 6px 接缝，浅色 / 深色主题令牌单源同步。</li><li><strong>修复</strong>：同一连接多次打开不再导致先前终端全部断开（此前超出服务端 sshd <code>MaxSessions</code> 上限时，新开标签会误关共享连接，连累已打开的所有终端；现正确区分连接断开与服务端拒绝，后者仅提示原因）。</li><li><strong>发布</strong>：新增 GitHub Releases 自动打包（macOS 通用二进制 / Windows NSIS 安装包与便携版 / Linux deb·rpm·便携版），自本版本起提供各平台下载。</li><li><strong>依赖</strong>：Wails v3 升级至 v3.0.0-beta.28。</li></ul><h2 id="v0-1-0-·-2026-10-03" tabindex="-1">v0.1.0 · 2026-10-03 <a class="header-anchor" href="#v0-1-0-·-2026-10-03" aria-label="Permalink to &quot;v0.1.0 · 2026-10-03&quot;">​</a></h2><p>首个发布版本（2026-05-18 开始开发）。</p><ul><li><strong>连接管理</strong>：分组树形组织、拖拽调整归属；密码 / 私钥 / 交互式三种认证，敏感信息 AES-256-GCM 加密存储；支持导入 <code>~/.ssh/config</code> 主机。</li><li><strong>终端</strong>：基于 xterm.js 的 PTY 终端（xterm-256color），WebGL 渲染、右键菜单复制粘贴、断开后回车即刻重连。</li><li><strong>SFTP 文件管理</strong>：远端目录树 + 双栏浏览，上传 / 下载 / 删除；从系统文件浏览器拖入上传、拖出下载，实时进度与取消。</li><li><strong>远程文件编辑</strong>：Monaco Editor 直接编辑远程文件（⌘S 写回服务器），按扩展名识别 40+ 种语言。</li><li><strong>服务器监控</strong>：CPU / 内存 / 磁盘 / 进程 / 网络全覆盖，ECharts 网卡流量趋势，复用 SSH 连接免重复认证。</li><li><strong>SSH 密钥管理</strong>：生成（Ed25519 / RSA / ECDSA）、导入、管理密钥对；被连接引用的密钥受删除保护。</li><li><strong>端口转发</strong>：本地端口转发（SSH 隧道），按连接分组，内置 MySQL / Redis / PostgreSQL 等常用预设。</li><li><strong>HTTPS 证书管理</strong>：集成 acme.sh 远程签发与续签（Let&#39;s Encrypt 等主流 CA、DNS 提供商配置、操作日志持久化）。</li><li><strong>个性化</strong>：中英双语、浅色 / 深色主题、7 套终端配色。</li><li><strong>文档站</strong>：VitePress 文档站上线并自动部署 GitHub Pages（2026-09-02）。</li></ul>',11)])])}const S=e(s,[["render",l]]);export{h as __pageData,S as default};
